import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from sklearn.preprocessing import StandardScaler

MAX_DRIVERS = 2

def design(feats):
    # Calculate effect sizes (difference in means between outcome groups)
    effect_sizes = []
    for i, fid in enumerate(feats.ids):
        group0 = feats.x[feats.y == 0, i]
        group1 = feats.x[feats.y == 1, i]
        effect_size = np.mean(group1) - np.mean(group0)
        effect_sizes.append(abs(effect_size))

    # Select top features by effect size
    top_indices = np.argsort(effect_sizes)[::-1][:10]
    top_fids = [feats.ids[i] for i in top_indices]

    # Remove near-duplicates based on correlation
    keep_fids = []
    for fid in top_fids:
        if not any(np.abs(np.corrcoef(feats.x[:, feats.column(fid)], 
                                      feats.x[:, feats.column(other_fid)])[0,1]) > 0.6 
                   for other_fid in keep_fids):
            keep_fids.append(fid)
        if len(keep_fids) >= MAX_DRIVERS:
            break

    # If no strong signals, return empty design
    if not keep_fids:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # For mechanism discovery, we look for interactions among top features
    # Use mutual information to identify potential interaction partners
    mi_scores = mutual_info_classif(feats.x[:, [feats.column(fid) for fid in keep_fids]], feats.y)
    top_driver_indices = np.argsort(mi_scores)[::-1][:MAX_DRIVERS]
    drivers = tuple([keep_fids[i] for i in top_driver_indices])

    # Include all features in regression (for linear terms)
    columns = tuple(keep_fids)

    # Look for product terms between top features
    products = []
    for i, fid1 in enumerate(keep_fids):
        for j, fid2 in enumerate(keep_fids[i+1:], i+1):
            # Add interaction term if both features are drivers
            if fid1 in drivers and fid2 in drivers:
                products.append((fid1, fid2))

    # Weighted score: sum of top features weighted by effect sizes
    loadings = {}
    for i, fid in enumerate(keep_fids):
        if i < MAX_DRIVERS:
            loadings[fid] = effect_sizes[feats.column(fid)]

    return Design(drivers=drivers, columns=columns, products=tuple(products), loadings=loadings)

